import copy
from climate_grid.scenario import converge_matrix, compare_matrix, _validate_converge_matrix

def matrix_with(rows, tol=0.5):
    return {
        "schema": "climate-grid/cvm-v1",
        "tolerance": tol,
        "layers": [{"element": "e", "region": "r"}],
        "data": rows,
    }

def row(s, count, interval, state, rank):
    return {"scenario": s, "count": count,
            "states": {"stable": count if state=="stable" else 0,
                       "uncertain": count if state=="uncertain" else 0,
                       "divergent": count if state=="divergent" else 0},
            "interval": interval, "state": state, "rank": rank}

# boundary: hi == tol -> stable; lo == tol (hi>tol) -> uncertain; lo > tol -> divergent
m = matrix_with([
    row("a", 1, [0.2, 0.5], "stable", 1),
    row("b", 1, [0.5, 0.8], "uncertain", 2),
    row("c", 1, [0.6, 0.9], "divergent", 3),
])
_validate_converge_matrix(m)
print("boundary states ok")

# hi == tol but marked uncertain -> reject
bad = copy.deepcopy(m); bad["data"][0]["state"] = "uncertain"
try:
    _validate_converge_matrix(bad); print("FAIL")
except ValueError as e: print("boundary reject ok:", e)

# rank tie on hi: consecutive ranks must follow scenario order
tie = matrix_with([
    row("a", 1, [0.1, 0.4], "stable", 1),
    row("b", 1, [0.2, 0.4], "stable", 2),
])
_validate_converge_matrix(tie)
print("tie order ok")
tie_bad = copy.deepcopy(tie)
tie_bad["data"][0]["rank"], tie_bad["data"][1]["rank"] = 2, 1
try:
    _validate_converge_matrix(tie_bad); print("FAIL tie")
except ValueError as e: print("tie reject ok:", e)

# converge_matrix output round-trips through compare_matrix (validator) fine
def cv_result(rows):
    return {"schema": "climate-grid/cv1", "scales": ["a", "b"],
            "tolerance": 0.5, "factor": 2.0, "data": rows}
def cv_row(s, interval, state, rank):
    return {"scenario": s, "count": 1, "pair": ["a", "b"], "peak": 0.5,
            "interval": interval, "state": state, "rank": rank}
it = lambda r: {"element": "e", "region": "r", "result": r}
m1 = converge_matrix([it(cv_result([
    cv_row("s1", [0.1, 0.4], "stable", 1),
    cv_row("s2", [0.2, 0.4], "stable", 2),
    cv_row("s3", None, None, None),
]))])
out = compare_matrix([{"name": "x", "matrix": m1}, {"name": "y", "matrix": m1}])
print("roundtrip ok:", [ (d["scenario"], d["rank"]) for d in out["data"]])
